'use strict';
// V60.1 — engagements et crises médiatiques, moteur pur.
(function(root,factory){const api=factory(typeof module==='object'&&module.exports?require('./press-relations.js'):root.CDPressRelations);if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.CDPressEvents=api})(typeof globalThis==='object'?globalThis:null,function(press){
const copy=x=>JSON.parse(JSON.stringify(x)),bounded=n=>Math.max(0,Math.min(100,Math.round(n)));
const requireValid=(p,m)=>{if(!p)throw Error(m)};
const QUESTIONS=Object.freeze({results:{topic:'form',question:'Comment réagir aux derniers résultats ?'},derby:{topic:'derby',question:'Comment abordez-vous ce derby ?'},injuries:{topic:'injury',question:'Comment gérez-vous les absences ?'},market:{topic:'transfers',question:'Quels sont les objectifs du recrutement ?'},ambition:{topic:'objectives',question:'Quel objectif annoncez-vous ?'}});
function start(clubId){return {version:1,press:press.create(clubId),promises:[],crises:[],archive:[],lastWeek:0};}
function validate(s){requireValid(s&&s.version===1&&s.press&&Array.isArray(s.promises)&&Array.isArray(s.crises)&&Array.isArray(s.archive)&&Number.isInteger(s.lastWeek)&&s.lastWeek>=0,'Etat média invalide');press.validate(s.press);requireValid(new Set(s.promises.map(p=>p.id)).size===s.promises.length,'Promesses dupliquées');return true;}
function question(key){requireValid(QUESTIONS[key],'Sujet inconnu');return {...QUESTIONS[key],key};}
function answer(state,{questionKey,tone,season,week,performance=0}){validate(state);const q=question(questionKey),n=copy(state),r=press.interview(n.press,{topic:q.topic,tone,season,week,performance});n.press=r.state;n.archive.push({type:'answer',questionKey,tone,season,week});return {state:n,event:r.event};}
function promise(state,{id,kind,target,season,week,deadline}){validate(state);requireValid(typeof id==='string'&&id&&['wins','points','position'].includes(kind)&&Number.isInteger(target)&&target>=0&&Number.isInteger(season)&&season>=1&&Number.isInteger(week)&&week>=0&&Number.isInteger(deadline)&&deadline>week&&!state.promises.some(p=>p.id===id),'Promesse invalide');const n=copy(state);n.promises.push({id,kind,target,season,week,deadline,status:'pending'});n.archive.push({type:'promise',id,season,week});return n;}
function tick(state,{season,week,metrics={}}){validate(state);requireValid(Number.isInteger(season)&&season>=1&&Number.isInteger(week)&&week>=0&&week>=state.lastWeek,'Semaine invalide');const n=copy(state),effects=[];for(const p of n.promises){if(p.status!=='pending'||p.season!==season||week<p.deadline)continue;const met=Number.isFinite(metrics[p.kind])&&metrics[p.kind]>=0;const fulfilled=met&&(p.kind==='position'?metrics.position<=p.target:metrics[p.kind]>=p.target);p.status=!met?'unverified':fulfilled?'fulfilled':'broken';const delta=p.status==='fulfilled'?6:p.status==='broken'?-9:0;n.press.fanTrust=bounded(n.press.fanTrust+delta);n.press.boardPressure=bounded(n.press.boardPressure-delta);effects.push({type:'promiseResult',id:p.id,status:p.status,delta});}
for(const crisis of n.crises){if(crisis.status!=='active')continue;if(week>=crisis.started+crisis.weeks){crisis.status='resolved';effects.push({type:'crisisResolved',id:crisis.id});}else{n.press.mediaTrust=bounded(n.press.mediaTrust-crisis.severity);n.press.boardPressure=bounded(n.press.boardPressure+crisis.severity);}}
n.lastWeek=week;n.archive.push(...effects.map(x=>({...x,season,week})));validate(n);return {state:n,effects};}
function crisis(state,{id,kind,severity=3,weeks=2,week}){validate(state);requireValid(typeof id==='string'&&id&&['controversy','bad-form','supporters'].includes(kind)&&Number.isInteger(severity)&&severity>=1&&severity<=10&&Number.isInteger(weeks)&&weeks>=1&&weeks<=8&&Number.isInteger(week)&&week>=state.lastWeek&&!state.crises.some(c=>c.id===id),'Crise invalide');const n=copy(state);n.crises.push({id,kind,severity,weeks,started:week,status:'active'});n.archive.push({type:'crisis',id,week});return n;}
function briefing(state,results=[]){validate(state);const p=press.briefing(state.press,{lastResults:results});return {...p,openPromises:state.promises.filter(x=>x.status==='pending').length,activeCrises:state.crises.filter(x=>x.status==='active').length};}
return Object.freeze({start,validate,question,answer,promise,tick,crisis,briefing});
});
